arguments:
{"script":"cat > count_procs.sh <<'EOF'
#!/bin/bash

echo $(ps -e --no-headers | wc -l)
EOF
chmod +x count_procs.sh

# start 5 background processes that run for 60 seconds each
sleep 60 & sleep 60 & sleep 60 & sleep 60 & sleep 60 &

# run the script to display the count
./count_procs.sh
"}
